// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ConversationForm) predicate.ConversationForm {
	return predicate.ConversationForm(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ConversationForm) predicate.ConversationForm {
	return predicate.ConversationForm(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ConversationForm) predicate.ConversationForm {
	return predicate.ConversationForm(sql.NotPredicates(p))
}
